"use client";

/**
 * AskAboutArea — property-level Q&A over OSM amenities.
 *
 * Answers are computed by the AI service from POI data (brand + distance),
 * never generated by an LLM, so the distance is always the real one.
 */

import { useState } from "react";
import { ApiError, askAboutArea, type AreaAnswer } from "../lib/api";
import { formatDistance } from "../lib/format";

interface AskAboutAreaProps {
  propertyId: number;
}

const SUGGESTIONS = [
  "Nearest supermarket",
  "Gyms nearby",
  "Primary schools within 2 miles",
  "Nearest train station",
  "Parks nearby",
  "Pharmacy near me",
];

const CATEGORY_ICONS: Record<string, string> = {
  supermarket: "🛒",
  convenience: "🏪",
  fitness: "🏋️",
  school: "🎓",
  nursery: "🧸",
  pharmacy: "💊",
  doctors: "🩺",
  dentist: "🦷",
  hospital: "🏥",
  park: "🌳",
  playground: "🛝",
  station: "🚂",
  cafe: "☕",
  restaurant: "🍽️",
  pub: "🍺",
  bar: "🍸",
};

export default function AskAboutArea({ propertyId }: AskAboutAreaProps) {
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState<AreaAnswer | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const ask = async (text: string) => {
    const trimmed = text.trim();
    if (!trimmed) return;

    setLoading(true);
    setError(null);
    try {
      setAnswer(await askAboutArea(propertyId, trimmed));
    } catch (err) {
      setAnswer(null);
      setError(
        err instanceof ApiError
          ? err.message
          : "Could not answer that right now. Please try again.",
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <section className="bg-white rounded-xl border p-4">
      <h2 className="font-semibold mb-1 flex items-center gap-2">
        <span aria-hidden>💬</span> Ask about this area
      </h2>
      <p className="text-sm text-gray-500 mb-3">
        Real answers from OpenStreetMap — shops, schools, gyms, parks and
        transport, with distances from this property.
      </p>

      <form
        onSubmit={(event) => {
          event.preventDefault();
          void ask(question);
        }}
        className="flex flex-col sm:flex-row gap-2"
      >
        <label htmlFor="area-question" className="sr-only">
          Ask a question about the area
        </label>
        <input
          id="area-question"
          type="text"
          value={question}
          onChange={(event) => setQuestion(event.target.value)}
          maxLength={200}
          placeholder="How far is the nearest Tesco?"
          className="flex-1 px-3 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
        />
        <button
          type="submit"
          disabled={loading || !question.trim()}
          className="px-4 py-2.5 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 disabled:opacity-50"
        >
          {loading ? "Checking…" : "Ask"}
        </button>
      </form>

      <div className="flex flex-wrap gap-2 mt-3">
        {SUGGESTIONS.map((suggestion) => (
          <button
            key={suggestion}
            type="button"
            onClick={() => {
              setQuestion(suggestion);
              void ask(suggestion);
            }}
            disabled={loading}
            className="px-3 py-1 bg-gray-100 hover:bg-gray-200 rounded-full text-xs text-gray-700 disabled:opacity-50"
          >
            {suggestion}
          </button>
        ))}
      </div>

      <div aria-live="polite" className="mt-4">
        {loading && <p className="text-sm text-gray-500 animate-pulse">Checking nearby amenities…</p>}

        {error && (
          <p role="alert" className="text-sm text-red-600">
            {error}
          </p>
        )}

        {answer && !loading && (
          <div className="space-y-3">
            <p className="text-gray-900 leading-relaxed">{answer.answer}</p>

            {answer.results.length > 0 && (
              <ul className="divide-y border rounded-lg">
                {answer.results.map((place) => (
                  <li
                    key={`${place.category}-${place.name}-${place.distance_m}`}
                    className="flex items-center justify-between gap-3 px-3 py-2 text-sm"
                  >
                    <span className="flex items-center gap-2 min-w-0">
                      <span aria-hidden>{CATEGORY_ICONS[place.category] ?? "📍"}</span>
                      <span className="truncate">
                        <span className="text-gray-900">{place.name}</span>
                        {place.street && place.street !== place.name && (
                          <span className="text-gray-500"> · {place.street}</span>
                        )}
                        {place.opening_hours && (
                          <span className="block text-xs text-gray-400">
                            {place.opening_hours}
                          </span>
                        )}
                      </span>
                    </span>
                    <span className="text-right text-gray-600 shrink-0">
                      {formatDistance(place.distance_m)}
                      <span className="block text-xs text-gray-400">
                        ~{place.walk_time_min} min walk
                      </span>
                    </span>
                  </li>
                ))}
              </ul>
            )}

            <p className="text-xs text-gray-400">
              Distances are straight-line; walking time is an estimate at{" "}
              {answer.walk_assumption ?? "3 mph"}. Data{" "}
              <a
                href="https://www.openstreetmap.org/copyright"
                target="_blank"
                rel="noopener noreferrer"
                className="underline"
              >
                {answer.attribution}
              </a>{" "}
              (ODbL). Opening hours and store presence can change — check before
              travelling.
            </p>
          </div>
        )}

        {!answer && !loading && !error && (
          <p className="text-sm text-gray-400">
            Try “Is there a park nearby?” or “What gyms are nearby?”.
          </p>
        )}
      </div>
    </section>
  );
}
